style_ax(ax4a, title='Distribution of MoM % Changes', xlabel='MoM Change (%)', ylabel='Frequency')

# Top 10 largest absolute MoM changes
top_mom = df.dropna(subset=['MoM_Pct']).nlargest(10, 'MoM_Pct')[['Date', 'Crude_Oil_Price', 'MoM_Pct']].copy()
top_mom['Date'] = top_mom['Date'].dt.strftime('%Y-%m')
ax4b.barh(top_mom['Date'][::-1], top_mom['MoM_Pct'][::-1], color=ACCENT, alpha=0.8, edgecolor='white')
for i, (val, date) in enumerate(zip(top_mom['MoM_Pct'][::-1], top_mom['Date'][::-1])):
    ax4b.text(val + 0.3, i, f'+{val:.1f}%', va='center', fontsize=8, color=PRIMARY)
style_ax(ax4b, title='Top 10 Largest MoM % Increases', xlabel='MoM Change (%)')
fig4.tight_layout()
chart4_b64 = fig_to_base64(fig4)

