#!/usr/bin/env python3
"""
Generate a comprehensive HTML report on Global Crude Oil Price Trends (1970-2026).
All statistics and KPIs are computed directly from the data.
"""

import base64
import io
import json
from datetime import datetime

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import matplotlib.ticker as mticker
import numpy as np
import pandas as pd

# ── Load Data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10
df['Month'] = df['Date'].dt.month

# Month-over-month change
df['MoM_Abs'] = df['Crude_Oil_Price'].diff()
df['MoM_Pct'] = df['Crude_Oil_Price'].pct_change() * 100

# Year-over-year change (12-month lag)
df['YoY_Abs'] = df['Crude_Oil_Price'].diff(12)
df['YoY_Pct'] = df['Crude_Oil_Price'].pct_change(12) * 100

# Rolling volatility (12-month rolling std of MoM % change)
df['Rolling_Vol'] = df['MoM_Pct'].rolling(window=12).std()

# ── KPI Calculations ──────────────────────────────────────────────────────
price_min = df['Crude_Oil_Price'].min()
price_max = df['Crude_Oil_Price'].max()
date_min_price = df.loc[df['Crude_Oil_Price'].idxmin(), 'Date']
date_max_price = df.loc[df['Crude_Oil_Price'].idxmax(), 'Date']
overall_range = price_max - price_min

# CAGR
n_years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
first_price = df['Crude_Oil_Price'].iloc[0]
last_price = df['Crude_Oil_Price'].iloc[-1]
cagr = ((last_price / first_price) ** (1 / n_years) - 1) * 100

# Maximum MoM change
max_mom_abs_idx = df['MoM_Abs'].abs().idxmax()
max_mom_abs = df.loc[max_mom_abs_idx, 'MoM_Abs']
max_mom_abs_date = df.loc[max_mom_abs_idx, 'Date']
max_mom_pct_idx = df['MoM_Pct'].abs().idxmax()
max_mom_pct = df.loc[max_mom_pct_idx, 'MoM_Pct']
max_mom_pct_date = df.loc[max_mom_pct_idx, 'Date']

# Maximum YoY change
max_yoy_pct_idx = df['YoY_Pct'].abs().idxmax()
max_yoy_pct = df.loc[max_yoy_pct_idx, 'YoY_Pct']
max_yoy_pct_date = df.loc[max_yoy_pct_idx, 'Date']

# Decade stats
decade_stats = df.groupby('Decade').agg(
    Mean=('Crude_Oil_Price', 'mean'),
    Median=('Crude_Oil_Price', 'median'),
    Std=('Crude_Oil_Price', 'std'),
    Min=('Crude_Oil_Price', 'min'),
    Max=('Crude_Oil_Price', 'max'),
    MoM_Vol=('MoM_Pct', 'std'),
    Count=('Crude_Oil_Price', 'count')
).reset_index()

highest_decade = decade_stats.loc[decade_stats['Mean'].idxmax(), 'Decade']

# Overall std
overall_std = df['Crude_Oil_Price'].std()

# Descriptive statistics
price_mean = df['Crude_Oil_Price'].mean()
price_median = df['Crude_Oil_Price'].median()
price_p25 = df['Crude_Oil_Price'].quantile(0.25)
price_p75 = df['Crude_Oil_Price'].quantile(0.75)
price_p90 = df['Crude_Oil_Price'].quantile(0.90)
price_skew = df['Crude_Oil_Price'].skew()
price_kurt = df['Crude_Oil_Price'].kurtosis()

# ── Chart Generation Helpers ──────────────────────────────────────────────
PRIMARY = '#1a365d'
SECONDARY = '#2b6cb0'
ACCENT = '#e53e3e'
HIGHLIGHT = '#dd6b20'
BG = '#f7fafc'
GRID_COLOR = '#e2e8f0'

CHART_BG = '#ffffff'

def fig_to_base64(fig, dpi=130):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor=CHART_BG)
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64

def style_ax(ax, title='', xlabel='', ylabel=''):
    ax.set_facecolor(CHART_BG)
    if title:
        ax.set_title(title, fontsize=13, fontweight='bold', color=PRIMARY, pad=12)
    if xlabel:
        ax.set_xlabel(xlabel, fontsize=10, color='#4a5568')
    if ylabel:
        ax.set_ylabel(ylabel, fontsize=10, color='#4a5568')
    ax.tick_params(colors='#4a5568', labelsize=8)
    ax.grid(True, alpha=0.3, color=GRID_COLOR, linestyle='--')
    ax.spines['top'].set_visible(False)
    ax.spines['right'].set_visible(False)
    ax.spines['left'].set_color('#cbd5e0')
    ax.spines['bottom'].set_color('#cbd5e0')

# ── Chart 1: Full Time Series with Annotations ───────────────────────────
fig1, ax1 = plt.subplots(figsize=(14, 5.5))
ax1.plot(df['Date'], df['Crude_Oil_Price'], color=SECONDARY, linewidth=0.9, alpha=0.95)
ax1.fill_between(df['Date'], df['Crude_Oil_Price'], alpha=0.12, color=SECONDARY)

# Key event annotations
annotations = [
    ('1973-10', '1973 Oil\nEmbargo', 25, 40),
    ('1979-01', 'Iranian\nRevolution', 40, 80),
    ('1986-01', '1986 Price\nCollapse', 14, 55),
    ('1990-08', 'Gulf\nWar', 35, 75),
    ('2008-07', '2008 Peak\n$147', 160, 100),
    ('2014-06', 'Shale\nGlut', 107, 140),
    ('2020-04', 'COVID-19\nCrash', 18, 60),
    ('2022-06', 'Russia-Ukraine\nSpike', 117, 90),
]
for date_str, label, price, arrow_y in annotations:
    dt = pd.Timestamp(date_str)
    row = df[df['Date'] == dt]
    if row.empty:
        # find nearest
        idx = df['Date'].searchsorted(dt)
        if idx >= len(df):
            idx = len(df) - 1
        actual_price = df.loc[idx, 'Crude_Oil_Price']
        actual_dt = df.loc[idx, 'Date']
    else:
        actual_price = row['Crude_Oil_Price'].values[0]
        actual_dt = dt
    ax1.annotate(label, xy=(actual_dt, actual_price), xytext=(actual_dt, arrow_y),
                fontsize=7, color=ACCENT, fontweight='bold',
                arrowprops=dict(arrowstyle='->', color=ACCENT, lw=1),
                ha='center', va='bottom')

style_ax(ax1, title='Global Crude Oil Price (USD/bbl) — 1970 to 2026',
         xlabel='', ylabel='USD per Barrel')
ax1.yaxis.set_major_formatter(mticker.FormatStrFormatter('$%.0f'))
fig1.tight_layout()
chart1_b64 = fig_to_base64(fig1)

# ── Chart 2: Decade Average Prices ────────────────────────────────────────
fig2, ax2 = plt.subplots(figsize=(10, 5))
decades = decade_stats['Decade'].astype(str) + 's'
bars = ax2.bar(decades, decade_stats['Mean'], color=SECONDARY, alpha=0.85, edgecolor='white', linewidth=1.5)
# Highlight highest decade
max_idx = decade_stats['Mean'].idxmax()
bars[max_idx].set_color(ACCENT)
bars[max_idx].set_alpha(0.9)
for i, (val, std) in enumerate(zip(decade_stats['Mean'], decade_stats['Std'])):
    ax2.errorbar(i, val, yerr=std, fmt='none', ecolor='#4a5568', capsize=4, capthick=1.5)
    ax2.text(i, val + std + 2, f'${val:.1f}', ha='center', va='bottom', fontsize=9, fontweight='bold', color=PRIMARY)
style_ax(ax2, title='Average Crude Oil Price by Decade (with Std Dev error bars)',
         xlabel='Decade', ylabel='Average Price (USD/bbl)')
fig2.tight_layout()
chart2_b64 = fig_to_base64(fig2)

# ── Chart 3: Rolling Volatility ───────────────────────────────────────────
fig3, ax3 = plt.subplots(figsize=(14, 4))
vol_data = df.dropna(subset=['Rolling_Vol'])
ax3.fill_between(vol_data['Date'], vol_data['Rolling_Vol'], alpha=0.35, color=HIGHLIGHT)
ax3.plot(vol_data['Date'], vol_data['Rolling_Vol'], color=HIGHLIGHT, linewidth=0.8)
style_ax(ax3, title='12-Month Rolling Volatility (Std Dev of MoM % Change)',
         xlabel='', ylabel='Volatility (%)')
fig3.tight_layout()
chart3_b64 = fig_to_base64(fig3)

# ── Chart 4: MoM % Change Distribution ────────────────────────────────────
fig4, (ax4a, ax4b) = plt.subplots(1, 2, figsize=(12, 4.5))
mom_data = df['MoM_Pct'].dropna()
ax4a.hist(mom_data, bins=60, color=SECONDARY, alpha=0.8, edgecolor='white')
ax4a.axvline(0, color=ACCENT, linewidth=1.5, linestyle='--')
style_ax(ax4a, title='Distribution of MoM % Changes', xlabel='MoM Change (%)', ylabel='Frequency')

# Top 10 largest absolute MoM changes
top_mom = df.dropna(subset=['MoM_Pct']).nlargest(10, 'MoM_Pct')[['Date', 'Crude_Oil_Price', 'MoM_Pct']].copy()
top_mom['Date'] = top_mom['Date'].dt.strftime('%Y-%m')
ax4b.barh(top_mom['Date'][::-1], top_mom['MoM_Pct'][::-1], color=ACCENT, alpha=0.8, edgecolor='white')
for i, (val, date) in enumerate(zip(top_mom['MoM_Pct'][::-1], top_mom['Date'][::-1])):
    ax4b.text(val + 0.3, i, f'+{val:.1f}%', va='center', fontsize=8, color=PRIMARY)
style_ax(ax4b, title='Top 10 Largest MoM % Increases', xlabel='MoM Change (%)')
fig4.tight_layout()
chart4_b64 = fig_to_base64(fig4)

# ── Chart 5: Price Distribution ───────────────────────────────────────────
fig5, (ax5a, ax5b) = plt.subplots(1, 2, figsize=(12, 4.5))
ax5a.hist(df['Crude_Oil_Price'], bins=50, color=SECONDARY, alpha=0.8, edgecolor='white')
ax5a.axvline(price_mean, color=ACCENT, linewidth=1.5, linestyle='--', label=f'Mean: ${price_mean:.1f}')
ax5a.axvline(price_median, color=HIGHLIGHT, linewidth=1.5, linestyle='--', label=f'Median: ${price_median:.1f}')
ax5a.legend(fontsize=8)
style_ax(ax5a, title='Distribution of Monthly Crude Oil Prices', xlabel='Price (USD/bbl)', ylabel='Frequency')

# Box plot by decade
decade_groups = [group['Crude_Oil_Price'].values for _, group in df.groupby('Decade')]
decade_labels = [f"{d}s" for d in sorted(df['Decade'].unique())]
bp = ax5b.boxplot(decade_groups, labels=decade_labels, patch_artist=True, showfliers=True,
                   flierprops=dict(marker='o', markersize=2, alpha=0.4))
for patch in bp['boxes']:
    patch.set_facecolor(SECONDARY)
    patch.set_alpha(0.5)
style_ax(ax5b, title='Price Distribution by Decade', xlabel='Decade', ylabel='Price (USD/bbl)')
fig5.tight_layout()
chart5_b64 = fig_to_base64(fig5)

# ── Chart 6: Decade Volatility Comparison ─────────────────────────────────
fig6, ax6 = plt.subplots(figsize=(10, 5))
decade_labels = decade_stats['Decade'].astype(str) + 's'
x_pos = np.arange(len(decade_labels))
width = 0.35
ax6.bar(x_pos - width/2, decade_stats['Std'], width, label='Price Std Dev', color=SECONDARY, alpha=0.8)
ax6.bar(x_pos + width/2, decade_stats['MoM_Vol'], width * 2, label='MoM Volatility (Std Dev %)', color=HIGHLIGHT, alpha=0.7)
ax6.set_xticks(x_pos)
ax6.set_xticklabels(decade_labels)
ax6.legend(fontsize=9)
style_ax(ax6, title='Price Dispersion vs. Monthly Volatility by Decade',
         xlabel='Decade', ylabel='Value')
fig6.tight_layout()
chart6_b64 = fig_to_base64(fig6)

# ── Chart 7: YoY % Change Time Series ────────────────────────────────────
fig7, ax7 = plt.subplots(figsize=(14, 4.5))
yoy_data = df.dropna(subset=['YoY_Pct'])
ax7.plot(yoy_data['Date'], yoy_data['YoY_Pct'], color=SECONDARY, linewidth=0.7, alpha=0.8)
ax7.fill_between(yoy_data['Date'], yoy_data['YoY_Pct'], 0,
                  where=yoy_data['YoY_Pct'] >= 0, alpha=0.2, color='green')
ax7.fill_between(yoy_data['Date'], yoy_data['YoY_Pct'], 0,
                  where=yoy_data['YoY_Pct'] < 0, alpha=0.2, color=ACCENT)
ax7.axhline(0, color='#4a5568', linewidth=0.8)
style_ax(ax7, title='Year-over-Year % Change in Crude Oil Price',
         xlabel='', ylabel='YoY Change (%)')
fig7.tight_layout()
chart7_b64 = fig_to_base64(fig7)

# ── Prepare Decade Table Data ─────────────────────────────────────────────
decade_table_rows = ''
for _, row in decade_stats.iterrows():
    decade_table_rows += f"""<tr>
        <td>{int(row['Decade'])}s</td>
        <td>${row['Mean']:.2f}</td>
        <td>${row['Median']:.2f}</td>
        <td>${row['Std']:.2f}</td>
        <td>${row['Min']:.2f}</td>
        <td>${row['Max']:.2f}</td>
        <td>${row['Max'] - row['Min']:.2f}</td>
        <td>{row['MoM_Vol']:.2f}%</td>
    </tr>"""

# ── Decade-by-Decade Narrative ────────────────────────────────────────────
def decade_narrative(decade, stats_row):
    d = int(decade)
    mean = stats_row['Mean']
    std = stats_row['Std']
    mn = stats_row['Min']
    mx = stats_row['Max']
    vol = stats_row['MoM_Vol']
    sub = df[df['Decade'] == decade]

    # Find max MoM change in this decade
    max_up = sub.dropna(subset=['MoM_Pct']).nlargest(1, 'MoM_Pct')
    max_down = sub.dropna(subset=['MoM_Pct']).nsmallest(1, 'MoM_Pct')

    parts = [f"The {d}s saw an average price of <strong>${mean:.2f}/bbl</strong> with a standard deviation of ${std:.2f}, ranging from ${mn:.2f} to ${mx:.2f}."]

    if d == 1970:
        parts.append("The decade began with prices below $2/bbl — a stable, regulated era. The 1973 OPEC oil embargo triggered the first major price shock, quadrupling prices from ~$3 to over $12 by early 1974. The Iranian Revolution of 1979 then drove prices above $40, ending the decade at unprecedented highs.")
    elif d == 1980:
        parts.append("The early 1980s continued the price surge, peaking near $40 in early 1981. However, the 1986 price collapse — driven by Saudi Arabia abandoning its swing-producer role and flooding the market — sent prices crashing below $15, a decline of over 60%. The rest of the decade saw prices stabilize in the $15–$20 range.")
    elif d == 1990:
        parts.append("Prices remained largely range-bound between $15–$25 for much of the decade. The Gulf War in 1990 caused a brief spike above $35, but prices quickly retreated. The Asian Financial Crisis of 1997–98 and increased OPEC production pushed prices to a low near $10 by late 1998, before a sharp recovery into 1999.")
    elif d == 2000:
        parts.append("This was the decade of the great oil price super-cycle. Driven by surging Chinese demand, tight supply, and financial speculation, prices rose steadily from ~$25 to an all-time peak of ~$147 in July 2008 — a nearly 6x increase. The 2008 financial crisis then triggered the largest price collapse in modern history, with prices falling below $35 within six months.")
    elif d == 2010:
        parts.append("Prices recovered quickly after the 2008 crash, stabilizing above $80 for most of the decade. The Arab Spring (2011), Libyan supply disruptions, and Iranian sanctions kept prices elevated. However, the US shale revolution dramatically increased supply, and OPEC's November 2014 decision not to cut production triggered a second major price collapse, from ~$110 to below $30 by early 2016.")
    elif d == 2020:
        parts.append("The COVID-19 pandemic caused the most dramatic demand shock in oil market history. In April 2020, prices briefly turned negative for WTI futures, while the benchmark crude price in this dataset fell to near $18. The subsequent recovery was remarkably swift — prices climbed back above $80 by 2022, fueled by the Russia-Ukraine conflict which drove prices to a decade-high above $117. Since 2023, prices have moderated into the $60–$80 range as supply adjustments and demand normalization take hold.")

    if not max_up.empty:
        mu = max_up.iloc[0]
        parts.append(f"Largest monthly increase: <strong>+{mu['MoM_Pct']:.1f}%</strong> in {mu['Date'].strftime('%B %Y')}.")
    if not max_down.empty:
        md = max_down.iloc[0]
        parts.append(f"Largest monthly decline: <strong>{md['MoM_Pct']:.1f}%</strong> in {md['Date'].strftime('%B %Y')}.")

    return ' '.join(parts)

